    <script type="text/javascript">

         $(document).ready(function(){
            $("#shadow").css("height", $(document).height()).hide();
            $(".lightSwitcher").click(function(){
               $("#shadow").toggle();
               if ($("#shadow").is(":hidden"))
                  $(this).html("lights off").removeClass("turnedOff");
                else
                  $(this).html("lights on").addClass("turnedOff");
            });

         });

    </script>


